import {cf} from './chinese-first.js';
import {isDone} from './model.js';
export const substoryUnit=r=>r.city+'｜'+r.region;
export function substoryRow(r,{data,progress,esc,link,check,embedded=false}){
 const done=isDone(progress,'substories',r.id);
 const refs=r.sourceRefs.map(id=>{const s=data.substorySources.find(s=>s.id===id);return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a>`;}).join(' · ');
 const detail=`<p class="unlock"><strong>解鎖前置</strong> ${esc(r.unlock)}</p><p><strong>時段／回訪</strong> ${esc(r.timeOfDay)}</p>${r.prerequisites.length?'<p>前置核對：'+r.prerequisites.map(id=>link('collections',(isDone(progress,'substories',id)?'已勾選 ':'待核對 ')+id,{category:'substories',target:id})).join(' · ')+'</p>':''}<h4>具體步驟</h4><ol>${r.steps.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol>${r.gifts?'<h4>需要的禮物與購買地點</h4><p class="muted">備齊後依NPC實際要求交付；表格不是固定送禮順序。</p><div class="table-wrap"><table><thead><tr><th>禮物</th><th>購買地點</th></tr></thead><tbody>'+r.gifts.map(g=>'<tr><td>'+esc(g.item)+'</td><td>'+esc(g.shop)+'</td></tr>').join('')+'</tbody></table></div>':''}<p class="completion"><strong>完成條件</strong> ${esc(r.completion)}</p>${r.tips.length?'<ul class="substory-tips">'+r.tips.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':''}<p class="source-links">查核 ${esc(r.checkedAt)} · ${refs}</p>`;
 return `<article class="row substory-row ${done?'done':''}" id="entry-${esc(r.id)}">${check('substories',r.id,r.id+' · '+r.nameZh).replace('</span></label>','</span><small class="cf-original">（'+esc(r.label)+'）</small></label>')}<div class="collectible-meta"><span>最早第${r.minChapter}章 · ${esc(substoryUnit(r))}</span><span>${esc(r.route)}</span></div>${!done||!embedded?'<p class="compact-location"><strong>觸發地點</strong> '+esc(r.location)+'</p>':''}${embedded&&!done?'<div class="row-body">'+detail+'</div>':`<details id="substory-detail-${esc(r.id)}"><summary>${done?'回看地點、':'展開'}前置、步驟與來源</summary>${done&&embedded?'<p><strong>觸發地點</strong> '+esc(r.location)+'</p>':''}${detail}</details>`}<div class="row-footer">${embedded?link('collections','到支線查漏',{category:'substories',target:r.id}):link('roadmap','到章節路線',{chapter:r.chapterId,target:r.id})}<small>${esc(r.id)}</small></div></article>`;
}
